import{_ as s,o as a,c as i,a2 as e}from"./chunks/framework.CnJ-JtFX.js";const k=JSON.parse('{"title":"EP.12 自由画布的代价","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.12-grapesjs-basics.md","filePath":"comics/EP.12-grapesjs-basics.md","lastUpdated":1792683644000}'),o={name:"comics/EP.12-grapesjs-basics.md"};function l(n,t,d,r,h,p){return a(),i("div",null,[...t[0]||(t[0]=[e(`<h1 id="ep-12-自由画布的代价" tabindex="-1">EP.12 自由画布的代价 <a class="header-anchor" href="#ep-12-自由画布的代价" aria-label="Permalink to &quot;EP.12 自由画布的代价&quot;">​</a></h1><blockquote><p>对应章节：<a href="./../guide/12-grapesjs-basics">guide/12-grapesjs-basics</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ol><li><strong>困境</strong>：标签君把 GrapesJS 当成&quot;想怎么拖就怎么拖&quot;的玩具，随手拖一堆 div 进去，结果导出的 HTML 是 div 套 div 的&quot;div 地狱&quot;，没有语义化标签、样式全是内联。</li><li><strong>揭秘</strong>：像素酱点出 GrapesJS 五大模块——Blocks（能拖什么）、Components（画布有什么）、Styles（CSS 怎么存）、Storage（数据存哪）、Commands（能执行什么）。</li><li><strong>实证</strong>：注册 Section / Text / Button / Image 四个 Block，从左侧拖入画布，点&quot;导出&quot;按钮拿到 <code>editor.getHtml()</code> + <code>editor.getCss()</code>。</li><li><strong>结案</strong>：码叔收束到「自由不等于无约束」——Storage 自动存 localStorage、Styles 走 CSSOM、导出要在 load 之后。</li></ol><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第一格-自由画布的困境" tabindex="-1">第一格：自由画布的困境 <a class="header-anchor" href="#第一格-自由画布的困境" aria-label="Permalink to &quot;第一格：自由画布的困境&quot;">​</a></h3><p>GrapesJS 的画布直接操作 DOM——拖进去的每个元素都是真实 HTML 节点。这意味着：</p><ul><li>没有 Schema 约束，运营可以拖任意嵌套结构；</li><li>没有组件协议，所有组件都是通用 div + 内联样式；</li><li>没有字段模型，表单值要自己从 DOM 收集。</li></ul><p>&quot;自由&quot;的代价是导出的 HTML 质量完全取决于使用者的前端素养。如果不做约束，拖出来的页面会是维护噩梦。</p><h3 id="第二格-五大模块" tabindex="-1">第二格：五大模块 <a class="header-anchor" href="#第二格-五大模块" aria-label="Permalink to &quot;第二格：五大模块&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模块</th><th>职责</th><th>API</th></tr></thead><tbody><tr><td>Blocks</td><td>左侧可拖入模板</td><td><code>editor.Blocks.add(id, {...})</code></td></tr><tr><td>Components</td><td>DOM 模型层</td><td><code>editor.Components.addComponent(...)</code></td></tr><tr><td>Styles</td><td>CSS 规则管理</td><td><code>editor.Styles.getAll()</code></td></tr><tr><td>StorageManager</td><td>持久化</td><td><code>editor.store()</code> / <code>editor.load()</code></td></tr><tr><td>Commands</td><td>可执行操作</td><td><code>editor.runCommand(&#39;get-html&#39;)</code></td></tr></tbody></table><p>五大模块通过事件总线通信。你不需要直接操作 DOM——所有修改走 Components 模型层，GrapesJS 负责同步到 iframe。</p><h3 id="第三格-block-注册与导出" tabindex="-1">第三格：Block 注册与导出 <a class="header-anchor" href="#第三格-block-注册与导出" aria-label="Permalink to &quot;第三格：Block 注册与导出&quot;">​</a></h3><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">editor.Blocks.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;button&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  label: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Button&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  category: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Basic&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  content: { type: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;button&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, content: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Click me&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, styles: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p><code>content</code> 可以是字符串 HTML 或组件对象。组件对象能指定 type、styles、traits 等。</p><p>导出：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> html</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> editor.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getHtml</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 画布 body 内 HTML</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> css</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> editor.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getCss</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// CSS 规则</span></span></code></pre></div><h3 id="第四格-存储与导出时机" tabindex="-1">第四格：存储与导出时机 <a class="header-anchor" href="#第四格-存储与导出时机" aria-label="Permalink to &quot;第四格：存储与导出时机&quot;">​</a></h3><p>StorageManager 默认存 localStorage。<code>autosave: true</code> 自动存，<code>autoload: true</code> 自动读。lab 里手动在 <code>component:update</code> 事件调 <code>editor.store()</code>。</p><p><code>getHtml()</code> / <code>getCss()</code> 必须在 <code>editor.on(&#39;load&#39;)</code> 之后调，否则画布还没渲染完。</p><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><ol><li><strong>CSS 必须引入</strong>：<code>grapesjs/dist/css/grapes.min.css</code> 不引入的话面板样式丢失但不报错。</li><li><strong>不要直接操作 iframe DOM</strong>：通过 Components 模型层修改，直接操作 DOM 会导致模型视图不一致。</li><li><strong>Block 的 styles 全局注入</strong>：多次拖入会注入多次相同 CSS 规则，建议用类名隔离。</li><li><strong>getHtml 要在 load 之后</strong>：编辑器初始化是异步的，用 <code>editor.on(&#39;load&#39;, ...)</code> 确保就绪。</li><li><strong>StorageManager 的 key 要隔离</strong>：不同章节用不同 localStorage key，避免互相覆盖。</li></ol><h2 id="自测" tabindex="-1">自测 <a class="header-anchor" href="#自测" aria-label="Permalink to &quot;自测&quot;">​</a></h2><details><summary><b>1. GrapesJS 和 tmagic-editor 的画布最本质的区别是什么？</b></summary><p>GrapesJS 的编辑器和画布是<strong>单进程</strong>——编辑器持有 iframe 的 contentDocument，直接在里面操作 DOM，不需要 DSL 同步。tmagic-editor 是<strong>双进程</strong>——编辑器在父窗口、画布在 iframe 跑独立 runtime，通过 <code>window.magic</code> 通信传 DSL。</p><p>单进程的好处是简单（没有通信开销、没有 DSL 序列化），代价是编辑器和画布共享 JS 上下文、样式隔离靠 iframe 天然沙箱。双进程的好处是完全隔离（编辑器包不影响画布、画布可以独立部署），代价是通信复杂、要维护 DSL 同步。</p></details><details><summary><b>2. Block 的 content 字段有哪两种形式？各自适用场景？</b></summary><p>两种形式：</p><ul><li><strong>字符串 HTML</strong>：<code>content: &#39;&lt;div class=&quot;card&quot;&gt;...&lt;/div&gt;&#39;</code>。简单直接，适合静态内容、不需要 trait 的场景。</li><li><strong>组件对象</strong>：<code>content: { type: &#39;button&#39;, content: &#39;Click&#39;, styles: &#39;...&#39; }</code>。可以指定组件 type、内联样式、traits 等，适合需要自定义属性面板的组件。</li></ul><p>字符串形式拖入后就是纯 DOM，没有业务语义；组件对象形式可以挂 trait，让右侧面板出现定制字段。</p></details><details><summary><b>3. 为什么 GrapesJS 不适合做中后台表单？</b></summary><p>三个原因：</p><ol><li><strong>没有表单字段模型</strong>：每个 input 是独立 DOM 节点，没有统一的字段值管理和校验机制。amis/Formily 有 Field 模型，能声明式校验、联动。</li><li><strong>字段联动要手动写 JS</strong>：省市区联动在 GrapesJS 里要写 onChange 事件处理 DOM，amis 用 <code>source</code> + <code>autoFill</code> 声明式搞定。</li><li><strong>提交序列化困难</strong>：要遍历 DOM 收集 input 值，无法像 Schema 驱动那样直接 <code>JSON.stringify(schema.data)</code>。</li></ol><p>所以 GrapesJS 适合营销落地页、邮件模板这种&quot;视觉为主&quot;的场景，不适合中后台表单。</p></details>`,26)])])}const g=s(o,[["render",l]]);export{k as __pageData,g as default};
